-- `pnpm --filter @sportspark/api seed:dev --timezone America/Los_Angeles` plus a demo day of
-- fields, courts and activities, exported table by table. No real person, no secret: accounts use
-- the local identity provider (issuer sportspark-local) and sign in only with the staging passcode.
-- Loaded once with triggers paused (session_replication_role = replica) because the rows are
-- already consistent; never load it into a database that holds real data.
set session_replication_role = replica;
